def _expansion_base(delegations: int, paid: int, verifier: int, manager_calls: int, manager_rounds: int) -> dict[str, int]:
    return {"delegations": delegations, "paid_worker_calls": paid, "verifier_calls": verifier,
            "manager_calls": manager_calls, "manager_rounds": manager_rounds}


def _claim(value: str, sources: dict[str, dict[str, str]]) -> dict[str, Any]:
    return {"value": value, "provenance": [{"source": name, "sha256": source["sha256"], "claim_status": "approved"} for name, source in sorted(sources.items())]}


INTENT_FIELDS = {
    "problem", "intended_users", "outcomes", "scope", "exclusions", "constraints",
    "assumptions", "acceptance_criteria", "risks", "open_decisions", "decision_owners",
    "allowed_specialists", "prohibited_capabilities", "delegation_matrix", "approval_matrix",
    "budget_safety_envelope", "boundaries", "amendment_lineage", "approval_history",
    "next_lane_eligibility",
}


def validate_shaper_intent(intent: object) -> dict[str, Any]:
    """Normalize approved intent for the v2 contract without mutating callers.

    V1 intent did not carry a verifier allowance.  New contracts preserve that
    input as an explicit default of two total verifier calls.
    """
    if not isinstance(intent, dict) or not INTENT_FIELDS <= set(intent) <= INTENT_FIELDS | {"max_verifier_calls", "expansion_headroom"}:
        raise DeliveryContractError("shaper_intent is invalid")
    intent = dict(intent)
    intent.setdefault("max_verifier_calls", 2)
    intent.setdefault("expansion_headroom", {})
    _text(intent["problem"], "problem")
    for name in ("intended_users", "outcomes", "scope", "exclusions", "constraints", "assumptions", "acceptance_criteria"):
        values = _list(intent[name], name, nonempty=True)
        for value in values:
            _text(value, name)
    for name in ("risks", "open_decisions", "decision_owners", "allowed_specialists", "prohibited_capabilities", "amendment_lineage", "approval_history", "next_lane_eligibility"):
        _list(intent[name], name, nonempty=name in {"risks", "allowed_specialists", "prohibited_capabilities", "approval_history", "next_lane_eligibility"})
    for name in ("delegation_matrix", "approval_matrix", "budget_safety_envelope", "boundaries"):
        _mapping(intent[name], name)
    for specialist in intent["allowed_specialists"]:
        specialist = _mapping(specialist, "allowed specialist", keys={"role", "capabilities", "definition_digest", "maximum_instances"})
        _text(specialist["role"], "allowed specialist role")
        capabilities = _list(specialist["capabilities"], "allowed specialist capabilities", nonempty=True)
        if len(capabilities) != len(set(capabilities)) or any(capability not in CAPABILITY_TO_RUNTIME for capability in capabilities):
            raise DeliveryContractError("allowed specialist capabilities contain an unsupported or duplicate value")
        _sha(specialist["definition_digest"], "allowed specialist definition_digest")
        if type(specialist["maximum_instances"]) is not int or specialist["maximum_instances"] < 1:
            raise DeliveryContractError("allowed specialist maximum_instances is invalid")
    if intent["approval_matrix"].get("provider_dispatch") != "Flow_grant":
        raise DeliveryContractError("provider dispatch must require a Flow grant")
    delegation = intent["delegation_matrix"]
    if set(delegation) != {"max_delegations", "delegated_expansion"} or type(delegation["max_delegations"]) is not int or delegation["max_delegations"] < 1:
        raise DeliveryContractError("delegation_matrix is invalid")
    envelope = intent["budget_safety_envelope"]
    if set(envelope) != {"enforceable", "observations"}:
        raise DeliveryContractError("budget_safety_envelope is invalid")
    enforceable = _mapping(envelope["enforceable"], "budget_safety_envelope enforceable", keys=ENFORCEABLE_LIMIT_FIELDS)
    for name in ("max_concurrent", "max_replans", "runtime_seconds", "retries", "max_manager_calls", "max_manager_rounds", "max_paid_worker_calls"):
        minimum = 1 if name in {"max_concurrent", "runtime_seconds", "max_manager_calls", "max_manager_rounds"} else 0
        if type(enforceable[name]) is not int or enforceable[name] < minimum:
            raise DeliveryContractError(f"{name} is invalid")
    for name in ("tools", "paths", "outputs"):
        values = _list(enforceable[name], name, nonempty=True)
        if len(values) != len(set(values)) or any(not isinstance(value, str) or not value for value in values):
            raise DeliveryContractError(f"{name} is invalid")
    if not set(enforceable["tools"]).issubset({"read", "edit", "test"}) or enforceable["paths"] != ["charter-scoped"] or not set(enforceable["outputs"]).issubset({"diff", "test", "receipt"}):
        raise DeliveryContractError("enforceable tools, paths, or outputs are unsupported")
    if enforceable["max_concurrent"] > delegation["max_delegations"] or enforceable["max_paid_worker_calls"] > delegation["max_delegations"]:
        raise DeliveryContractError("concurrency or paid-worker limit exceeds max_delegations")
    if type(intent["max_verifier_calls"]) is not int or intent["max_verifier_calls"] not in {1, 2}:
        raise DeliveryContractError("max_verifier_calls must be one or two")
    intent["expansion_headroom"] = validate_expansion_headroom(intent["expansion_headroom"], _expansion_base(
        delegation["max_delegations"], enforceable["max_paid_worker_calls"], intent["max_verifier_calls"],
        enforceable["max_manager_calls"], enforceable["max_manager_rounds"]))
    # The flag is derived, never independent: it states whether any headroom exists.
    if type(delegation["delegated_expansion"]) is not bool or delegation["delegated_expansion"] != any(intent["expansion_headroom"].values()):
        raise DeliveryContractError("delegated_expansion must state whether any expansion headroom is sealed")
    _list(envelope["observations"], "budget_safety_envelope observations")
    return intent


def _intent(work_id: str, sources: dict[str, dict[str, str]], approved: dict[str, Any]) -> dict[str, Any]:
    """Project a reviewed per-run intent artifact without guessing Markdown semantics."""
    approved = validate_shaper_intent(approved)
    claimed = lambda value: _claim(value, sources)
    return {
        "problem": claimed(approved["problem"]),
        **{name: [claimed(value) for value in approved[name]] for name in
           ("intended_users", "outcomes", "scope", "exclusions", "constraints", "assumptions", "acceptance_criteria")},
        "source_evidence": [{"source": name, "sha256": source["sha256"], "claim_status": "approved", "provenance": source["path"]} for name, source in sorted(sources.items())],
        **{name: approved[name] for name in ("risks", "open_decisions", "decision_owners", "allowed_specialists",
           "prohibited_capabilities", "delegation_matrix", "approval_matrix", "budget_safety_envelope", "max_verifier_calls",
           "expansion_headroom", "boundaries", "amendment_lineage", "approval_history", "next_lane_eligibility")},
    }


def _seal(record: dict[str, Any], validator) -> dict[str, Any]:

    # transition.  It seals immutable delivery artifacts under a per-run lock
    # and makes the one run.json replacement its commit point.  Keep the
    # public lifecycle API unchanged while delegating that atomic operation.
    if event_name == "start-plan":
        if artifacts or dispositions or note:
            return False, _load_run(work_id, root) or {}, [
                "start-plan does not accept artifact, disposition, or note overrides"
            ]
        current_start = _load_run(work_id, root)
        current_state = current_start.get("state") if current_start else None
        active_root = (root or repo_root()).resolve()
        declared = (current_start or {}).get("artifacts", {})
        source_paths = [declared.get("requirements"), declared.get("acceptance_criteria")]
        sources_exist = all(
            isinstance(path, str) and (active_root / path).is_file()
            for path in source_paths
        )
        revision = (current_start or {}).get("protocol_revision", 1)
        # Revision two carries approved artifact bindings. It must never bypass
        # authority sealing when those bytes are missing or unsafe. Revision
        # one predates the delivery contract and retains the legacy lifecycle.
        if current_state == STATE_PLANNING and (current_start or {}).get("delivery"):
            return seal_delivery_start_plan(work_id, root=active_root)
        if current_state in {STATE_DEFINITION_APPROVED, STATE_SOLUTION_APPROVED} and revision == PROTOCOL_REVISION_CURRENT:
            return seal_delivery_start_plan(work_id, root=active_root)
    transition = TRANSITIONS[event_name]
    current = _load_run(work_id, root)
    current_state = current.get("state") if current else None
    if current_state not in transition.from_states:
        expected = ", ".join(state or "<new>" for state in transition.from_states)
        actual = current_state or "<new>"
        return False, current or {}, [
            f"invalid transition: {event_name} requires {expected}; current state is {actual}"
        ]

    now = _now()
    payload = dict(current or {})
    payload.setdefault("schema_version", SCHEMA_VERSION)
    if current is None:
        payload["protocol_revision"] = PROTOCOL_REVISION_CURRENT
    payload.setdefault("work_id", work_id)
    payload.setdefault("created_at", now)
    payload["artifacts"] = dict(payload.get("artifacts", {}))
    payload["dispositions"] = dict(payload.get("dispositions", {}))
    payload["gates"] = dict(payload.get("gates", {}))
    previous_manifest = payload["artifacts"].get("orchestration_manifest")
    replacement_manifest = (artifacts or {}).get("orchestration_manifest")
    if previous_manifest and replacement_manifest and previous_manifest != replacement_manifest:
        return False, current or {}, ["orchestration_manifest cannot be replaced after it is recorded"]
    payload["artifacts"].update(artifacts or {})
    payload["dispositions"].update(dispositions or {})

    if event_name in {"approve-definition", "approve-solution"} and _protocol_revision(payload) == PROTOCOL_REVISION_CURRENT:
        active_root = (root or repo_root()).resolve()
        expected_prefix = f".flow/runs/{work_id}/"
        approval_names = (
            ("requirements", "acceptance_criteria", "shaper_intent", "orchestration_manifest")
            if event_name == "approve-definition" else ("solution",)
        )
        payload["approved_artifact_digests"] = dict(payload.get("approved_artifact_digests", {}))
        for name in approval_names:
            relative = payload["artifacts"].get(name)
            if not isinstance(relative, str) or not relative.startswith(expected_prefix):
                return False, current or {}, [f"missing for {transition.gate}: artifact:{name}"]
            path = active_root / relative
            if (not path.is_file() or path.is_symlink()
                    or not path.resolve().is_relative_to(active_root)):
                return False, current or {}, [f"{name} must be a current-run regular file"]
            payload["approved_artifact_digests"][name] = hashlib.sha256(path.read_bytes()).hexdigest()

    missing = _missing_gate_items(payload, transition)
    if missing:
        gate = f" for {transition.gate}" if transition.gate else ""
        return False, current or {}, [f"missing{gate}: {item}" for item in missing]

    orchestration_errors = _orchestration_gate_errors(
        work_id, event_name, payload, root=root
    )
    if orchestration_errors:
        return False, current or {}, orchestration_errors

    previous_state = current_state
    if transition.to_state == STATE_RETURN:
        next_state = payload.get("return_state")
        if not next_state or next_state in {STATE_PAUSED, STATE_BLOCKED, STATE_ARCHIVED}:
            return False, current or {}, ["missing valid return_state for resume"]
        payload.pop("return_state", None)
        next_lane = payload.pop("return_lane", None) or STATE_LANES.get(next_state, transition.lane)
    else:
        next_state = transition.to_state
        next_lane = transition.lane
    if event_name in {"pause", "block"} and previous_state:
        payload["return_state"] = previous_state
        payload["return_lane"] = payload.get("lane") or STATE_LANES.get(previous_state)
    payload["state"] = next_state
    payload["lane"] = next_lane
    payload["phase"] = next_state
    payload["updated_at"] = now
    payload["last_event"] = event_name
    payload["gates"][event_name] = now
    if note:
        payload["next_action"] = note
    else:
        payload.pop("next_action", None)

    event = {
        "at": now,
        "event": event_name,
        "from": previous_state,
        "to": next_state,
        "artifacts": artifacts or {},
        "dispositions": dispositions or {},
    }
    if event_name in {"approve-definition", "approve-solution"} and payload.get("approved_artifact_digests"):
        names = ("requirements", "acceptance_criteria", "shaper_intent", "orchestration_manifest") if event_name == "approve-definition" else ("solution",)
        event["approved_artifact_digests"] = {
            name: payload["approved_artifact_digests"][name] for name in names
        }
    if note:
        event["note"] = note

    _write_run(work_id, payload, root)
    _append_event(work_id, event, root)
    return True, payload, []


def verify(work_id: str, root: Path | None = None) -> tuple[bool, list[str], dict[str, Any]]:
    payload = status(work_id, root)
    if payload.get("state") == STATE_LEGACY:
        return True, ["legacy/inferred: no canonical run.json"], payload
    messages: list[str] = []
    ok = True
    if payload.get("schema_version") != SCHEMA_VERSION:
        ok = False
        messages.append(f"schema_version: expected {SCHEMA_VERSION}")
    try:
        _protocol_revision(payload)
    except ValueError as exc:
        ok = False
        messages.append(str(exc))
    try:
        events = _load_events(work_id, root)
    except ValueError as exc:
        return False, [str(exc)], payload
    lifecycle_events = [event for event in events if not str(event.get("event", "")).startswith("delivery-lead-")]
    if not lifecycle_events:
        ok = False
        messages.append("events: missing transition history")
    elif lifecycle_events[-1].get("to") != payload.get("state"):
        ok = False
        messages.append(
            f"state/history mismatch: run.json={payload.get('state')} events.jsonl={lifecycle_events[-1].get('to')}"
        )
    if payload.get("last_event") and lifecycle_events and lifecycle_events[-1].get("event") != payload.get("last_event"):
        ok = False
        messages.append("last_event does not match latest history event")
    if ok:
        messages.append("ok")
    return ok, messages, payload

